const int LED_ON = HIGH;
const int LED_DIRECTION_FORWARD = 1;
const int LED_DIRECTION_BACKWARD = -1;

void updateIndex(int& index, int numPins, int direction) {
  index += direction;
  if (index < 0) {
    index = numPins - 1;
  } else if (index >= numPins) {
    index = 0;
  }
}

void cycleLEDs(int interval) {
  if (outPins == NULL || sizeof(outPins) == 0) {
    // Handle error: outPins is invalid
    return;
  }

  const int numPins = sizeof(outPins) / sizeof(outPins[0]);
  static unsigned long lastChange = 0;
  static int currentIndex = 0;
  int nextIndex = 0;
  int direction = interval < 0 ? LED_DIRECTION_BACKWARD : LED_DIRECTION_FORWARD;

  if (millis() >= lastChange + abs(interval)) {
    updateIndex(nextIndex, numPins, direction);
    updateIndex(currentIndex, numPins, direction);

    // Turn off all LEDs
    for (int i = 0; i < numPins; i++) {
      if (i == currentIndex || i == nextIndex) {
        digitalWrite(outPins[i], LED_ON);
      } else {
        digitalWrite(outPins[i], LED_OFF);
      }
    }

    // Update timer
    lastChange = millis();
  }
}
```

