Here's an example of blocking read interrupted by signal, with EINTR handling in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Function to handle EINTR
void handle_eintr(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        exit(0);
    }
}

int main() {
    int fd = open("test.txt", O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(1);
    }

    // Register the EINTR handler
    signal(SIGINT, handle_eintr);

    char buffer[1024];
    ssize_t bytes_read;

    // Read in a loop until we get an error
    while (1) {
        bytes_read = read(fd, buffer, 1024);
        if (bytes_read == -1) {
            // Check for EINTR
            if (errno == EINTR) {
                // Signal was caught, continue to the next iteration
                continue;
            } else {
                // Some other error occurred, exit
                perror("read");
                close(fd);
                exit(1);
            }
        }

        // If we got no bytes, we're done
        if (bytes_read == 0) {
            break;
        }

        // Print the bytes we read
        printf("%.*s\n", bytes_read, buffer);
    }

    close(fd);
    return 0;
}
```

In this example, we open a file and start reading in a loop. We use `signal` to register a handler for the `SIGINT` signal, which is raised when we press Ctrl+C. The handler simply prints a message and exits the program.

Inside the read loop, we check if `read` returns `-1`. If it does, we check if the error is `EINTR`. If it is, we continue to the next iteration of the loop. If it's not `EINTR`, we print an error message and exit the program.

This way, we can handle the `SIGINT` signal and continue reading from the file without immediately exiting.

Here is an example C++ code snippet that reads network packets from a socket on port 888:

**Note:** This code assumes you have the `sys/socket.h` and `netinet/in.h` headers included for socket operations, and `unistd.h` for `close()` function.

```cpp
#include <iostream>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <string.h>
#include <arpa/inet.h>

#define PORT 888

class SocketReader {
public:
    SocketReader() {}

    // Function to create a socket and bind to a specific port
    void createSocket() {
        // Create a socket
        sock_ = socket(AF_INET, SOCK_STREAM, 0);
        if (sock_ < 0) {
            std::cerr << "Socket creation failed." << std::endl;
            return;
        }

        // Set address and port number
        struct sockaddr_in address;
        address.sin_family = AF_INET;
        address.sin_addr.s_addr = INADDR_ANY;
        address.sin_port = htons(PORT);

        // Bind the socket to the specified port
        if (bind(sock_, (struct sockaddr *)&address, sizeof(address)) < 0) {
            std::cerr << "Binding failed." << std::endl;
            close(sock_);
            return;
        }

        // Listen for incoming connections
        if (listen(sock_, 3) < 0) {
            std::cerr << "Listening failed." << std::endl;
            close(sock_);
            return;
        }

        std::cout << "Server listening on port " << PORT << std::endl;
    }

    // Function to accept incoming connections and read data from the socket
    void acceptAndRead() {
        // Accept incoming connections
        struct sockaddr_in clientAddress;
        socklen_t clientAddressLen = sizeof(clientAddress);
        int clientSocket = accept(sock_, (struct sockaddr *)&clientAddress, &clientAddressLen);
        if (clientSocket < 0) {
            std::cerr << "Accept failed." << std::endl;
            return;
        }

        // Read data from the socket
        char buffer[1024];
        int bytesRead = recv(clientSocket, buffer, 1024, 0);
        if (bytesRead < 0) {
            std::cerr << "Reading failed." << std::endl;
            close(clientSocket);
            return;
        }

        buffer[bytesRead] = '\0';  // Null terminate the string
        std::cout << "Received message: " << buffer << std::endl;

        // Close the client socket
        close(clientSocket);
    }

private:
    int sock_;
};

int main() {
    SocketReader reader;
    reader.createSocket();
    reader.acceptAndRead();
    return 0;
}
```

This code creates a socket, binds it to port 888, and listens for incoming connections. When a connection is accepted, it reads data from the socket and prints it to the console.

Please note that this is a basic example and may not handle all possible edge cases. For a more robust server, consider using a framework like Boost.Asio or Poco.

