```javascript
var w = 500;
var h = 500;
var r = 100; // radius of the rounded corner

var path = new Array();
path.push("M", 0, 0);
path.push("L", 0, h);
path.push("C", 0, h, r, h, r, h);
path.push("L", w, h);
path.push("C", w, h, w, h - r, w - r, h - r);
path.push("L", w - r, 0);
path.push("C", w - r, 0, w - r, 0, w, 0);
path.push("Z");

this.length = path.length * 10; // set the length of the path
this.point = function(t) {
    if (t <= this.length / 300) { // top left corner
        return [0, (t / (this.length / 300)) * h];
    } else if (t <= this.length / 300 * 2) { // top edge
        return [(t / (this.length / 300 * 2)) * w, h];
    } else if (t <= this.length / 300 * 3) { // top right corner
        return [(w - (t / (this.length / 300 * 3)) * w), h - (t / (this.length / 300 * 3)) * r];
    } else if (t <= this.length / 300 * 4) { // right edge
        return [(w - (t / (this.length / 300 * 4)) * w), (h - (t / (this.length / 300 * 4)) * r)];
    } else if (t <= this.length / 300 * 5) { // bottom right corner
        return [(w - r) - (t / (this.length / 300 * 5)) * (w - r), h - r - (t / (this.length / 300 * 5)) * (h - r)];
    } else if (t <= this.length / 300 * 6) { // bottom edge
        return [(w - r) - (t / (this.length / 300 * 6)) * (w - r), (h - r) - (t / (this.length / 300 * 6)) * (h - r)];
    } else if (t <= this.length / 300 * 7) { // bottom left corner
        return [(t / (this.length / 300 * 7)) * (w - r), (h - r) - (t / (this.length / 300 * 7)) * (h - r)];
    } else {
        return [(t / (this.length / 300 * 8)) * (w - r), 0];
    }
};
```

