                                foreach (var runChildElement3 in runChildElement2.Elements<Run>())
                                {
                                    headerRun.AppendChild(new Run());
                                    headerRun.AppendChild(new Paragraph());
                                    headerRun.AppendChild(new ParagraphProperties());
                                }
                            }
                        }
                    }
                }

                // Copy the footer from the source document
                var sourceFooter = sourceFooterPart.Document.Body;
                var targetFooter = targetFooterPart.Document.Body;
                sourceFooter.RemoveAllChildren();
                targetFooter.AppendChild(new FooterReference());
                targetFooter.AppendChild(new Paragraph());
                targetFooter.AppendChild(new ParagraphProperties());
                var footerRun = targetFooter.AppendChild(new Run());
                footerRun.Append(new Paragraph());
                var sourceFooterRun = sourceFooter.AppendChild(new Run());
                sourceFooterRun.Append(new Paragraph());
                sourceFooterRun.AppendChild(new ParagraphProperties());
                foreach (var child in sourceFooterRun.Elements<Run>())
                {
                    footerRun.AppendChild(new Run());
                    footerRun.AppendChild(new Paragraph());
                    footerRun.AppendChild(new ParagraphProperties());
                    foreach (var runChild in child.Elements<Run>())
                    {
                        footerRun.AppendChild(new Run());
                        footerRun.AppendChild(new Paragraph());
                        footerRun.AppendChild(new ParagraphProperties());
                        foreach (var runChildElement in runChild.Elements<Run>())
                        {
                            footerRun.AppendChild(new Run());
                            foreach (var runChildElement2 in runChildElement.Elements<Run>())
                            {
                                foreach (var runChildElement3 in runChildElement2.Elements<Run>())
                                {
                                    footerRun.AppendChild(new Run());
                                    footerRun.AppendChild(new Paragraph());
                                    footerRun.AppendChild(new ParagraphProperties());
                                }
                            }
                        }
                    }
                }

                // Copy the first 2 page contents from the source document
                foreach (var page in sourcePages)
                {
                    targetBody.AppendChild(new Paragraph());
                    targetBody.AppendChild(new ParagraphProperties());
                    targetBody.AppendChild(new Run());
                    foreach (var child in page.Elements<Run>())
                    {
                        targetBody.AppendChild(new Run());
                        foreach (var childElement in child.Elements<Run>())
                        {
                            targetBody.AppendChild(new Run());
                            foreach (var childElement2 in childElement.Elements<Run>())
                            {
                                targetBody.AppendChild(new Run());
                                foreach (var childElement3 in childElement2.Elements<Run>())
                                {
                                    targetBody.AppendChild(new Run());
                                }
                            }
                        }
                    }
                }

                // Copy the glossary from the source document
                if (sourceGlossaryPart.Document.Body.Elements<Paragraph>().Any())
                {
                    targetGlossaryPart.Document.Body.RemoveAllChildren();
                    targetGlossaryPart.Document.Body.Append(new Paragraph());
                    targetGlossaryPart.Document.Body.Append(new ParagraphProperties());
                    foreach (var para in sourceGlossaryPart.Document.Body.Elements<Paragraph>())
                    {
                        targetGlossaryPart.Document.Body.Append(new Paragraph());
                        targetGlossaryPart.Document.Body.Append(new ParagraphProperties());
                        foreach (var child in para.Elements<Run>())
                        {
                            targetGlossaryPart.Document.Body.Append(new Run());
                            foreach (var childElement in child.Elements<Run>())
                            {
                                targetGlossaryPart.Document.Body.Append(new Run());
                                foreach (var childElement2 in childElement.Elements<Run>())
                                {
                                    targetGlossaryPart.Document.Body.Append(new Run());
                                    foreach (var childElement3 in childElement2.Elements<Run>())
                                    {
                                        targetGlossaryPart.Document.Body.Append(new Run());
                                    }
                                }
                            }
                        }
                    }
                }

                // Copy the document settings from the source document
                if (sourceSettingsPart.DocumentSettings != null)
                {
                    targetSettingsPart.DocumentSettings = sourceSettingsPart.DocumentSettings;
                }

                // Save the target document
                targetDoc.Save();
            }
        }
    }
}
