```python
import hashlib
import time
import random

class Node:
    def __init__(self, id, address):
        self.id = id
        self.address = address
        self.balance = 0
        self.data = {}

    def deposit(self, data, lifetime, fee):
        data_hash = hashlib.sha256(data.encode()).hexdigest()
        if data_hash not in self.data:
            self.data[data_hash] = {'lifetime': lifetime, 'fee': fee}
            self.balance += self.calculate_deposit(len(data), lifetime)
        else:
            print(f"Data {data_hash} already exists.")

    def calculate_deposit(self, data_size, lifetime):
        return data_size * lifetime

    def update_lifetime(self, data_hash, new_lifetime):
        if data_hash in self.data:
            self.data[data_hash]['fee'] += new_lifetime - self.data[data_hash]['lifetime']
            self.data[data_hash]['lifetime'] = new_lifetime
            self.balance += self.calculate_deposit(len(self.data[data_hash]['data']), new_lifetime) - self.calculate_deposit(len(self.data[data_hash]['data']), self.data[data_hash]['lifetime'])
        else:
            print(f"Data {data_hash} does not exist.")

    def delete_data(self, data_hash):
        if data_hash in self.data:
            del self.data[data_hash]
            self.balance += self.calculate_deposit(0, self.data[data_hash]['lifetime'])
        else:
            print(f"Data {data_hash} does not exist.")

    def get_fee(self, data_hash, fee):
        if data_hash in self.data:
            self.balance -= fee
            self.data[data_hash]['fee'] += fee
        else:
            print(f"Data {data_hash} does not exist.")


class Blockchain:
    def __init__(self):
        self.chain = []
        self.nodes = {}
        self.block_number = 0

    def add_node(self, node):
        self.nodes[node.id] = node

    def add_data(self, data, lifetime, fee):
        data_hash = hashlib.sha256(data.encode()).hexdigest()
        for node_id in self.nodes:
            node = self.nodes[node_id]
            node.deposit(data, lifetime, fee)
            node.balance += fee / len(self.nodes)
            self.chain.append({
                'block_number': self.block_number,
                'node_id': node_id,
                'data_hash': data_hash,
                'fee': fee
            })
            self.block_number += 1

    def update_lifetime(self, data_hash, new_lifetime):
        for node_id in self.nodes:
            node = self.nodes[node_id]
            node.update_lifetime(data_hash, new_lifetime)

    def delete_data(self, data_hash):
        for node_id in self.nodes:
            node = self.nodes[node_id]
            node.delete_data(data_hash)

    def get_fee(self, data_hash):
        for node_id in self.nodes:
            node = self.nodes[node_id]
            node.get_fee(data_hash, self.chain[-1]['fee'] / len(self.nodes))


# Usage example
blockchain = Blockchain()

node1 = Node(1, "address1")
node2 = Node(2, "address2")
blockchain.add_node(node1)
blockchain.add_node(node2)

# Upload data
data = b"Hello, World!"
lifetime = 10
fee = 10
blockchain.add_data(data, lifetime, fee)

# Update lifetime of data
new_lifetime = 20
blockchain.update_lifetime(hashlib.sha256(data).hexdigest(), new_lifetime)

# Delete data
blockchain.delete_data(hashlib.sha256(data).hexdigest())

# Get fee for accessing data
blockchain.get_fee(hashlib.sha256(data).hexdigest())
```

