**Old-School Raycasting in GLSL**

This code is for a basic old-school raycaster implemented in GLSL. It's a simplified version and includes the following features:

* Raycasting from a 2D camera
* Rendering a 2D floor with heightmap
* Rendering 3D walls
* Basic color mapping

**Vertex Shader:**
```glsl
#version 330 core

layout(location = 0) in vec3 pos;
layout(location = 1) in vec2 uv;

out vec2 v_uv;
out vec3 v_pos;

void main() {
    gl_Position = vec4(pos, 1.0);
    v_uv = uv;
    v_pos = pos;
}
```

**Fragment Shader:**
```glsl
#version 330 core

precision highp float;

uniform vec2 resolution;
uniform mat4 view;
uniform mat4 projection;

in vec2 v_uv;
in vec3 v_pos;

out vec4 FragColor;

uniform sampler2D heightmap;
uniform int mapWidth;
uniform int mapHeight;

uniform vec3 rayOrigin;
uniform vec3 rayDirection;

// Maximum viewing distance
const int MAX_DISTANCE = 1000;

float getWallHeight(int x, int y) {
    return texture(heightmap, vec2(float(x) / mapWidth, float(y) / mapHeight)).r;
}

void main() {
    // Projective texture coordinates
    vec2 screenCoord = (gl_FragCoord.xy / resolution.xy) * 2.0 - 1.0;
    vec3 ray = normalize(rayDirection);
    vec3 move = normalize(cross(ray, vec3(0, 1, 0)));
    vec3 right = normalize(cross(ray, move));

    float wallHitX = rayOrigin.x;
    float wallHitY = rayOrigin.y;
    float wallHitDist = 0.0;

    for (int x = int(-resolution.x / 2); x <= resolution.x / 2; ++x) {
        for (int y = int(-resolution.y / 2); y <= resolution.y / 2; ++y) {
            if (x == 0 && y == 0) continue;

            vec3 pos = (wallHitX + x * 0.1) * right + (wallHitY + y * 0.1) * move;
            vec3 direction = normalize(pos - rayOrigin);
            float dist = length(pos - rayOrigin);

            if (dist < MAX_DISTANCE) {
                float wallHeight = getWallHeight(int(wallHitX + x * 0.1), int(wallHitY + y * 0.1));
                wallHitDist = dist;
                wallHitX = pos.x;
                wallHitY = pos.y;
            }
        }
    }

    // Calculate wall height
    float wallHeight = getWallHeight(int(wallHitX), int(wallHitY));
    vec3 diff = rayOrigin - wallHitX * right - wallHitY * move;
    vec3 proj = diff / length(diff);

    float wallLength = min(resolution.x, resolution.y);
    float wallHeightProj = wallHeight * length(diff.x * right + diff.y * move);

    // Calculate screen space position
    vec2 screenPos = (wallHitX * right + wallHitY * move) * 0.1;
    screenPos += vec2(resolution.x / 2, resolution.y / 2);

    // Calculate wall color
    vec3 wallColor = vec3(0.2, 0.2, 0.2);
    wallColor.r = wallHeight;
    wallColor.g = length(diff) * 0.1;
    wallColor.b = length(diff) * 0.1;

    // Draw floor
    if (length(diff) < wallHeightProj) {
        FragColor = vec4(0.0, 1.0, 0.0, 1.0);
    } else {
        // Draw wall
        FragColor = vec4(wallColor, 1.0);
    }
}
```

**Note:**

* You'll need to pass in the `heightmap` texture, `mapWidth`, and `mapHeight` uniforms to the fragment shader.
* The `rayOrigin` and `rayDirection` uniforms should be set to the 3D camera position and direction, respectively.
* The `view` and `projection` uniforms should be set to the view and projection matrices, respectively.

