namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    private $user;

    public function __construct(User $user)
    {
        $this->user = $user;
    }

    /**
     * Add a business name to the favorites list.
     *
     * @param string $name
     * @return void
     */
    public function add($name)
    {
        if (Auth::check()) {
            $favorite = Favorite::firstOrCreate(['user_id' => Auth::id(), 'name' => $name]);
            $favorite->save();
        } else {
            $sessionKey = 'favorites_' . Auth::guard()->getProvider()->getIdFromUser(Auth::guard()->getId());
            Cache::forget($sessionKey);
            Cache::forever($sessionKey, array_merge(Cache::get($sessionKey, []), [$name]));
        }
    }

    /**
     * Remove a business name from the favorites list.
     *
     * @param string $name
     * @return void
     */
    public function remove($name)
    {
        if (Auth::check()) {
            Favorite::where('user_id', Auth::id())->where('name', $name)->delete();
        } else {
            $sessionKey = 'favorites_' . Auth::guard()->getProvider()->getIdFromUser(Auth::guard()->getId());
            Cache::forget($sessionKey);
            $favorites = Cache::get($sessionKey, []);
            $favorites = array_filter($favorites, function ($favorite) use ($name) {
                return $favorite !== $name;
            });
            Cache::forever($sessionKey, $favorites);
        }
    }

    /**
     * Get the favorites list.
