private final AtomicReference<DequeState> state = new AtomicReference<>();

private static class DequeState {
    int modCount;
    int front;
    int rear;
    int size;
    E[] array;

    public DequeState(int modCount, int front, int rear, int size, E[] array) {
        this.modCount = modCount;
