// Function to map a memory region
int map_memory_region(void __user *addr, size_t length, unsigned long flags)
{
    struct vm_area_struct *vma;
    struct file *file = NULL;

    // Create an anonymous file for mapping
    file = anon_inode_getfile("[anon_inode:mmap]", &anon_inode_mmap_fops, NULL, O_RDWR);
    if (IS_ERR(file)) {
        printk(KERN_ERR "Error creating anonymous file.\n");
        return PTR_ERR(file);
    }

    // Map the file into the user space
    vma = do_anonymous_page(NULL, addr, length, file);
    if (!vma) {
        printk(KERN_ERR "Error mapping memory region.\n");
        return -1;
    }

    // Set the mapping to be executable
    set_memory_exec(vma->vm_start, vma->vm_end - vma->vm_start);
    return 0;
}

// The main part of the kernel module
static int __init my_init_module(void)
{
    // Map 4096 bytes at the virtual address 0x100000
    if (map_memory_region((void __user *)0x100000, 4096, 0)) {
        printk(KERN_ERR "Error mapping memory region.\n");
        return -1;
    }

    printk(KERN_INFO "Memory region mapped at 0x100000.\n");
