Here's a simplified implementation of TCP in TypeScript. This implementation includes packet creation, packet parsing, and basic functionality for a TCP connection.

**tcp.ts**
```typescript
interface TcpHeader {
  sourcePort: number;
  destinationPort: number;
  sequenceNumber: number;
  acknowledgementNumber: number;
  dataOffset: number;
  reserved: number;
  flags: number;
  windowSize: number;
  checksum: number;
  urgentPointer: number;
}

class Tcp {
  private header: TcpHeader;
  private data: Uint8Array;

  constructor(header: TcpHeader, data: Uint8Array) {
    this.header = header;
    this.data = data;
  }

  public static create(header: TcpHeader, data: Uint8Array): Tcp {
    return new Tcp(header, data);
  }

  public static parse(buffer: Uint8Array, offset: number): Tcp {
    const header = {
      sourcePort: buffer[offset++] & 0xff,
      destinationPort: buffer[offset++] & 0xff,
      sequenceNumber: buffer.readInt32BE(offset),
      acknowledgementNumber: buffer.readInt32BE(offset + 4),
      dataOffset: buffer[offset++] & 0xf,
      reserved: buffer[offset++] & 0xf,
      flags: buffer[offset++] & 0xff,
      windowSize: buffer[offset++] & 0xff,
      checksum: buffer[offset++] & 0xffff,
      urgentPointer: buffer[offset++] & 0xffff,
    };

    const dataOffset = header.dataOffset * 4;
    const data = buffer.slice(offset + 12, offset + 12 + dataOffset);

    return new Tcp(header, data);
  }

  public getSourcePort(): number {
    return this.header.sourcePort;
  }

  public getDestinationPort(): number {
    return this.header.destinationPort;
  }

  public getSequenceNumber(): number {
    return this.header.sequenceNumber;
  }

  public getAcknowledgementNumber(): number {
    return this.header.acknowledgementNumber;
  }

  public getData(): Uint8Array {
    return this.data;
  }

  public getChecksum(): number {
    return this.header.checksum;
  }

  public getUrgentPointer(): number {
    return this.header.urgentPointer;
  }

  public getFlags(): number {
    return this.header.flags;
  }

  public isSyn(): boolean {
    return (this.header.flags & 0x2) !== 0;
  }

  public isAck(): boolean {
    return (this.header.flags & 0x10) !== 0;
  }

  public isFin(): boolean {
    return (this.header.flags & 0x1) !== 0;
  }
}
```
This implementation provides methods for creating and parsing TCP packets. The `TcpHeader` interface represents the TCP header structure.

You can use this implementation as follows:

**example.ts**
```typescript
import { Tcp, TcpHeader } from './tcp';

const header: TcpHeader = {
  sourcePort: 1234,
  destinationPort: 5678,
  sequenceNumber: 0x12345678,
  acknowledgementNumber: 0x90abcdef,
  dataOffset: 5,
  reserved: 0,
  flags: 0x2, // SYN
  windowSize: 65535,
  checksum: 0,
  urgentPointer: 0,
};

const data = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8]);
const tcp = Tcp.create(header, data);

console.log(tcp.getSourcePort()); // 1234
console.log(tcp.getDestinationPort()); // 5678
console.log(tcp.getSequenceNumber()); // 305419896
console.log(tcp.getAcknowledgementNumber()); // 4294967295
console.log(tcp.getChecksum()); // 0
console.log(tcp.getUrgentPointer()); // 0

const buffer = new Uint8Array([0x12, 0x34, ...header, ...data]);
const parsedTcp = Tcp.parse(buffer, 2);

console.log(parsedTcp.getSourcePort()); // 1234
console.log(parsedTcp.getDestinationPort()); // 5678
console.log(parsedTcp.getSequenceNumber()); // 305419896
console.log(parsedTcp.getAcknowledgementNumber()); // 4294967295
console.log(parsedTcp.getChecksum()); // 0
console.log(parsedTcp.getUrgentPointer()); // 0

console.log(parsedTcp.isSyn()); // true
console.log(parsedTcp.isAck()); // false
console.log(parsedTcp.isFin()); // false
```
This example demonstrates how to create a TCP packet and parse it from a buffer. It also shows how to access the packet's fields and check its flags.

