Create a new React app using `create-react-app` and add the following components:

`src/App.js`:

```javascript
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [tasks, setTasks] = useState([]);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');

  useEffect(() => {
    axios.get('http://localhost:3001/tasks')
      .then(response => {
        setTasks(response.data);
      })
      .catch(error => {
        console.error(error);
      });
  }, []);

  const handleSubmit = (event) => {
    event.preventDefault();
    axios.post('http://localhost:3001/tasks', {
      title,
      description,
    })
      .then(response => {
        setTasks([...tasks, response.data]);
        setTitle('');
        setDescription('');
      })
      .catch(error => {
        console.error(error);
      });
  };

  const handleUpdate = (id, title, description) => {
    axios.put(`http://localhost:3001/tasks/${id}`, {
      title,
      description,
    })
      .then(response => {
        const updatedTasks = tasks.map((task) => {
          if (task.id === id) {
            return response.data;
          }
          return task;
        });
        setTasks(updatedTasks);
      })
      .catch(error => {
        console.error(error);
      });
  };

  const handleDelete = (id) => {
    axios.delete(`http://localhost:3001/tasks/${id}`)
      .then(() => {
        const updatedTasks = tasks.filter((task) => task.id !== id);
        setTasks(updatedTasks);
      })
      .catch(error => {
        console.error(error);
      });
  };

  return (
    <div>
      <h1>To-Do List App</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          placeholder="Title"
        />
        <input
          type="text"
          value={description}
          onChange={(event) => setDescription(event.target.value)}
          placeholder="Description"
        />
        <button type="submit">Add Task</button>
      </form>
      <ul>
        {tasks.map((task) => (
          <li key={task.id}>
            <h2>{task.title}</h2>
            <p>{task.description}</p>
            <button onClick={() => handleUpdate(task.id, task.title, task.description)}>Edit</button>
            <button onClick={() => handleDelete(task.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

**API Endpoints:**

*   `POST /tasks`: Creates a new task with the given title and description.
*   `GET /tasks`: Retrieves all tasks.
*   `PUT /tasks/:id`: Updates a task with the given ID, title, and description.
*   `DELETE /tasks/:id`: Deletes a task with the given ID.

**Note:** This is a basic example and does not include any authentication or authorization. You should add these features to your application depending on your requirements.

**Database Schema:**

```sql
CREATE TABLE tasks (
  id SERIAL PRIMARY KEY,
  title VARCHAR(255),
  description TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
```

This schema includes an ID field, title, description, created at, and updated at fields. The ID field is a primary key and auto-increments. The created at and updated at fields are timestamp fields that default to the current timestamp.

