extern "C" WEIGHT_PRECISION weights_h1[HIDDEN_NEURONS * HIDDEN_NEURONS];
extern "C" WEIGHT_PRECISION weights_o[OUTPUT_NEURONS * HIDDEN_NEURONS];

// Define the neural network activation functions
inline ap_fixed<16,8> sigmoid(ap_fixed<16,8> x) {
    return 1.0 / (1.0 + ap_exp(-x));
}

inline ap_fixed<16,8> sigmoid_derivative(ap_fixed<16,8> x) {
    return x * (1.0 - x);
}

// Define the neural network forward pass
void forward(ap_fixed<16,8> input[INPUT_NEURONS],
             ap_fixed<16,8> weights_h0[INPUT_NEURONS * HIDDEN_NEURONS],
             ap_fixed<16,8> weights_h1[HIDDEN_NEURONS * HIDDEN_NEURONS],
             ap_fixed<16,8> weights_o[OUTPUT_NEURONS * HIDDEN_NEURONS],
             ap_fixed<16,8> output[OUTPUT_NEURONS]) {
    // Initialize the hidden and output layers
    ap_fixed<16,8> hidden[INPUT_NEURONS];
    ap_fixed<16,8> hidden_next[HIDDEN_NEURONS];
    ap_fixed<16,8> output_next[OUTPUT_NEURONS];

    // Forward pass for the hidden layer
    for (int i = 0; i < INPUT_NEURONS; i++) {
        for (int j = 0; j < HIDDEN_NEURONS; j++) {
            hidden[j] += input[i] * weights_h0[i * HIDDEN_NEURONS + j];
        }
    }
    for (int i = 0; i < HIDDEN_NEURONS; i++) {
        hidden_next[i] = sigmoid(hidden[i]);
    }

    // Forward pass for the output layer
    for (int i = 0; i < HIDDEN_NEURONS; i++) {
        for (int j = 0; j < OUTPUT_NEURONS; j++) {
            output_next[j] += hidden_next[i] * weights_o[i * OUTPUT_NEURONS + j];
        }
    }
    for (int i = 0; i < OUTPUT_NEURONS; i++) {
        output[i] = sigmoid(output_next[i]);
    }

    // Forward pass for the second hidden layer
    ap_fixed<16,8> hidden_next_next[HIDDEN_NEURONS];
    for (int i = 0; i < HIDDEN_NEURONS; i++) {
        for (int j = 0; j < HIDDEN_NEURONS; j++) {
            hidden_next_next[i] += hidden_next[j] * weights_h1[j * HIDDEN_NEURONS + i];
        }
    }
    for (int i = 0; i < HIDDEN_NEURONS; i++) {
        hidden_next[i] = sigmoid(hidden_next_next[i]);
    }

    // Forward pass for the output layer
    for (int i = 0; i < HIDDEN_NEURONS; i++) {
        for (int j = 0; j < OUTPUT_NEURONS; j++) {
            output_next[j] += hidden_next[i] * weights_o[i * OUTPUT_NEURONS + j];
        }
    }
    for (int i = 0; i < OUTPUT_NEURONS; i++) {
        output[i] = sigmoid(output_next[i]);
    }
}

// Define the HLS stream interface for the neural network forward pass
inline void forward(ap_stream<INPUT_PRECISION> &input_stream,
                     ap_stream<ap_int<32> > &output_stream,
                     ap_fixed<16,8> weights_h0[INPUT_NEURONS * HIDDEN_NEURONS],
                     ap_fixed<16,8> weights_h1[HIDDEN_NEURONS * HIDDEN_NEURONS],
                     ap_fixed<16,8> weights_o[OUTPUT_NEURONS * HIDDEN_NEURONS]) {
    // Get the input tensor from the input stream
    INPUT_PRECISION input[INPUT_NEURONS];
    input_stream.read(input);

    // Get the output tensor from the output stream
    ap_int<32> output_int[OUTPUT_NEURONS];
    output_stream.read(output_int);

    // Perform the neural network forward pass
    forward(input, weights_h0, weights_h1, weights_o, output_int);

    // Write the output tensor to the output stream
    output_stream.write(output_int);
}

// Define the HLS stream interface for the neural network forward pass
inline void forward_bypass(ap_stream<INPUT_PRECISION> &input_stream,
                           ap_stream<ap_int<32> > &output_stream,
                           ap_fixed<16,8> weights_h0[INPUT_NEURONS * HIDDEN_NEURONS],
                           ap_fixed<16,8> weights_h1[HIDDEN_NEURONS * HIDDEN_NEURONS],
                           ap_fixed<16,8> weights_o[OUTPUT_NEURONS * HIDDEN_NEURONS]) {
    // Get the input tensor from the input stream
    INPUT_PRECISION input[INPUT_NEURONS];
    input_stream.read(input);

    // Perform the neural network forward pass
    ap_fixed<16,8> output[OUTPUT_NEURONS];
    forward(input, weights_h0, weights_h1, weights_o, output);

    // Write the output tensor to the output stream
    output_stream.write((ap_int<32>*)output);
}

// Define the HLS kernel for the neural network forward pass
void kernel(ap_stream<INPUT_PRECISION> &input_stream,
             ap_stream<ap_int<32> > &output_stream,
             ap_fixed<16,8> weights_h0[INPUT_NEURONS * HIDDEN_NEURONS],
             ap_fixed<16,8> weights_h1[HIDDEN_NEURONS * HIDDEN_NEURONS],
             ap_fixed<16,8> weights_o[OUTPUT_NEURONS * HIDDEN_NEURONS],
             hls::stream<ap_uint<512> > &data_stream,
             hls::stream<ap_uint<32> > &control_stream,
             ap_uint<512> &data_count,
             ap_uint<32> &control_count) {
    // Define the number of processing elements
    #pragma HLS array_partition variable=input_stream cyclic factor=4 dim=1

    // Process the input stream
    for (int i = 0; i < 1024; i++) {
        // Get the input tensor from the input stream
        INPUT_PRECISION input[INPUT_NEURONS];
        input_stream.read(input);

        // Perform the neural network forward pass
        ap_fixed<16,8> output[OUTPUT_NEURONS];
        forward(input, weights_h0, weights_h1, weights_o, output);

        // Write the output tensor to the output stream
        output_stream.write((ap_int<32>*)output);

        // Increment the data count
        data_count += 1;
    }

    // Increment the control count
    control_count += 1;
}

// Define the HLS kernel for the neural network forward pass with bypass
void kernel_bypass(ap_stream<INPUT_PRECISION> &input_stream,
                    ap_stream<ap_int<32> > &output_stream,
                    ap_fixed<16,8> weights_h0[INPUT_NEURONS * HIDDEN_NEURONS],
                    ap_fixed<16,8> weights_h1[HIDDEN_NEURONS * HIDDEN_NEURONS],
                    ap_fixed<16,8> weights_o[OUTPUT_NEURONS * HIDDEN_NEURONS],
                    hls::stream<ap_uint<512> > &data_stream,
                    hls::stream<ap_uint<32> > &control_stream,
                    ap_uint<512> &data_count,
                    ap_uint<32> &control_count) {
    // Define the number of processing elements
    #pragma HLS array_partition variable=input_stream cyclic factor=4 dim=1

    // Process the input stream
    for (int i = 0; i < 1024; i++) {
        // Get the input tensor from the input stream
        INPUT_PRECISION input[INPUT_NEURONS];
        input_stream.read(input);

        // Perform the neural network forward pass
        ap_fixed<16,8> output[OUTPUT_NEURONS];
        forward_bypass(input_stream, output_stream, weights_h0, weights_h1, weights_o);

        // Increment the data count
        data_count += 1;
    }

    // Increment the control count
    control_count += 1;
}
