Here's a basic implementation of a project management system in Python:

```python
# Project Management System

class Project:
    def __init__(self, name, start_date, end_date):
        self.name = name
        self.start_date = start_date
        self.end_date = end_date
        self.tasks = []
        self.resources = []
        self.risks = []
        self.tracked_data = {}

    def add_task(self, task):
        self.tasks.append(task)

    def add_resource(self, resource):
        self.resources.append(resource)

    def add_risk(self, risk):
        self.risks.append(risk)

    def track_data(self, data):
        self.tracked_data[data['task']] = data['status']

    def get_task_status(self, task):
        return self.tracked_data.get(task, "Not started")

    def get_resource_status(self, resource):
        status = {}
        for task in self.tasks:
            if resource in task.resources:
                status[task.name] = self.get_task_status(task.name)
        return status

    def get_risk_status(self):
        status = {}
        for risk in self.risks:
            status[risk.name] = risk.status
        return status


class Task:
    def __init__(self, name, start_date, end_date, resources=None):
        self.name = name
        self.start_date = start_date
        self.end_date = end_date
        self.resources = resources if resources else []
        self.status = "Not started"


class Resource:
    def __init__(self, name, availability):
        self.name = name
        self.availability = availability


class Risk:
    def __init__(self, name, status):
        self.name = name
        self.status = status


def create_project(name, start_date, end_date):
    return Project(name, start_date, end_date)


def create_task(name, start_date, end_date, resources=None):
    return Task(name, start_date, end_date, resources)


def create_resource(name, availability):
    return Resource(name, availability)


def create_risk(name, status):
    return Risk(name, status)


def main():
    # Create a project
    project = create_project("Sample Project", "2023-01-01", "2023-12-31")

    # Create tasks
    task1 = create_task("Task 1", "2023-01-01", "2023-01-31")
    task2 = create_task("Task 2", "2023-02-01", "2023-02-28")
    project.add_task(task1)
    project.add_task(task2)

    # Create resources
    resource1 = create_resource("Resource 1", "High")
    resource2 = create_resource("Resource 2", "Medium")
    project.add_resource(resource1)
    project.add_resource(resource2)

    # Create risks
    risk1 = create_risk("Risk 1", "High")
    risk2 = create_risk("Risk 2", "Low")
    project.add_risk(risk1)
    project.add_risk(risk2)

    # Track data
    project.track_data({"task": "Task 1", "status": "In progress"})
    project.track_data({"task": "Task 2", "status": "Not started"})

    # Print project status
    print("Project Status:")
    print(f"Project Name: {project.name}")
    print(f"Start Date: {project.start_date}")
    print(f"End Date: {project.end_date}")

    # Print task status
    print("\nTask Status:")
    for task in project.tasks:
        print(f"Task Name: {task.name}")
        print(f"Start Date: {(task.start_date) if task.start_date else 'N/A'}")
        print(f"End Date: {task.end_date}")
        print(f"Status: {project.get_task_status(task.name)}")

    # Print resource status
    print("\nResource Status:")
    for resource in project.resources:
        print(f"Resource Name: {resource.name}")
        print(f"Availability: {resource.availability}")
        print(f"Task Status: {project.get_resource_status(resource.name)}")

    # Print risk status
    print("\nRisk Status:")
    for risk in project.risks:
        print(f"Risk Name: {risk.name}")
        print(f"Status: {risk.status}")


if __name__ == "__main__":
    main()
```

This code defines a `Project` class that has methods to add tasks, resources, and risks. It also has methods to track data and get the status of tasks, resources, and risks. The `Task`, `Resource`, and `Risk` classes are used to create tasks, resources, and risks. The `create_project`, `create_task`, `create_resource`, and `create_risk` functions are used to create projects, tasks, resources, and risks. The `main` function demonstrates how to use these classes and functions to create a project, tasks, resources, and risks, and how to track data and get the status of tasks, resources, and risks.

