Here's a basic implementation of a Sprite Editor in JavaScript. This example uses HTML5 Canvas for rendering and event handling.

```javascript
// Sprite class
class Sprite {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.frames = [];
    this.currentFrame = 0;
    this.frameDuration = 1000 / 60;
    this.tickCount = 0;
    this.lastIndexOfUpdate = 0;
  }

  addFrame(image) {
    this.frames.push(image);
  }

  update() {
    this.tickCount++;
    if (this.tickCount > this.frameDuration) {
      this.tickCount = 0;
      this.currentFrame = (this.currentFrame + 1) % this.frames.length;
      this.lastIndexOfUpdate = Date.now();
    }
  }

  draw(context, x, y) {
    if (this.frames.length > 0) {
      context.drawImage(this.frames[this.currentFrame], x, y, this.width, this.height);
    }
  }
}

// SpriteEditor class
class SpriteEditor {
  constructor() {
    this.sprite = new Sprite(32, 32);
    this.canvas = document.getElementById('canvas');
    this.context = this.canvas.getContext('2d');
    this.x = 0;
    this.y = 0;
    this.width = 32;
    this.height = 32;
    this.mode = 'draw';
    this.frames = [];

    this.canvas.addEventListener('mousedown', (e) => this.handleMouseDown(e));
    this.canvas.addEventListener('mousemove', (e) => this.handleMouseMove(e));
    this.canvas.addEventListener('mouseup', (e) => this.handleMouseUp(e));
    this.canvas.addEventListener('mouseleave', (e) => this.handleMouseLeave(e));
    this.canvas.addEventListener('click', (e) => this.handleClick(e));
    this.canvas.addEventListener('dblclick', (e) => this.handleDblClick(e));
    window.requestAnimationFrame(this.draw.bind(this));
  }

  handleMouseDown(e) {
    if (this.mode === 'draw') {
      this.x = e.offsetX;
      this.y = e.offsetY;
      this.frames.push(this.context.getImageData(this.x, this.y, 1, 1));
    }
  }

  handleMouseMove(e) {
    if (this.mode === 'draw') {
      this.context.clearRect(0, 0, this.canvas.width, this.canvas.height);
      for (let i = 0; i < this.frames.length; i++) {
        this.context.putImageData(this.frames[i], i % 32, Math.floor(i / 32) * 32);
      }
      this.x = e.offsetX;
      this.y = e.offsetY;
      this.context.putImageData(this.frames[this.frames.length - 1], e.offsetX, e.offsetY);
    }
  }

  handleMouseUp(e) {
    if (this.mode === 'draw') {
      this.frames.push(this.context.getImageData(this.x, this.y, 1, 1));
    }
  }

  handleMouseLeave(e) {}

  handleClick(e) {
    if (this.mode === 'draw') {
      this.x = e.offsetX;
      this.y = e.offsetY;
      this.frames.push(this.context.getImageData(this.x, this.y, 1, 1));
    } else if (this.mode === 'addframe') {
      this.sprite.addFrame(this.context.getImageData(0, 0, 32, 32));
      this.mode = 'draw';
    }
  }

  handleDblClick(e) {
    if (this.mode === 'draw') {
      this.mode = 'addframe';
    }
  }

  update() {
    this.sprite.update();
  }

  draw() {
    this.context.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.sprite.draw(this.context, 0, 0);
    for (let i = 0; i < this.frames.length; i++) {
      this.context.putImageData(this.frames[i], i % 32, Math.floor(i / 32) * 32);
    }
    window.requestAnimationFrame(this.draw.bind(this));
  }
}

// Create a new SpriteEditor instance
new SpriteEditor();
```

This code creates a canvas element and handles the following events:

- Mouse down: starts drawing a frame
- Mouse move: draws the frame as the mouse moves
- Mouse up: ends drawing a frame
- Mouse leave: does nothing
- Click: adds the current frame to the sprite
- Dbl click: switches between draw and add frame modes

The sprite is updated every frame and drawn on the canvas along with the frames.

