```matlab
% Water Tank Simulation
% --------------------

% Water tank dimensions
L = 0.42;  % length (m)
W = 0.36;  % width (m)

% Wind speed
U = 2.5;  % wind speed (m/s)

% Density of water
rho = 1000;  % kg/m^3

% Depth of the water tank
H = 0.1;  % depth (m)

% Time step
dt = 0.01;

% Space step
dx = 0.01;
dy = 0.01;

% Number of grid points
nx = ceil(L/dx);
ny = ceil(W/dy);

% Create a 2D grid
x = (0:nx-1)*dx;
y = (0:ny-1)*dy;
[X, Y] = meshgrid(x, y);

% Initialize the free surface
eta = zeros(size(X));

% Physical parameters
g = 9.81;  % acceleration due to gravity (m/s^2)
k = sqrt((rho*g)/H);  % wave number
omega = sqrt(g*k);  % angular frequency

% Simulation time
t = 0:dt:10;

% Loop over time
for i = 1:length(t)
    % Update the free surface
    eta = eta + dt*omega*eta - (U/k)*diff(eta, 1)/(dx/2);

    % Plot the free surface
    figure;
    contourf(X, Y, eta, 30);
    colorbar;
    title(['Water Surface at t = ', num2str(t(i))]);
    drawnow;
    pause(0.1);
end
