```javascript
function searchJson(json, key) {
    let result = [];

    function recursiveSearch(obj, currentPath) {
        for (let k in obj) {
            let newPath = currentPath + (currentPath ? '.' : '') + k;
            if (k === key) {
                result.push({
                    value: obj[k],
                    path: newPath
                });
            } else if (typeof obj[k] === 'object') {
                recursiveSearch(obj[k], newPath);
            }
        }
    }

    recursiveSearch(json, '');
    return result;
}

