Here's a simple implementation of a Connect-4 game in Python:

```python
class Connect4:
    def __init__(self):
        self.board = [[' ' for _ in range(7)] for _ in range(6)]
        self.current_player = 'X'

    def print_board(self):
        print('  1 2 3 4 5 6 7')
        for i in range(6):
            row = str(i + 1) + ' '
            for j in range(7):
                row += self.board[i][j] + ' '
            print(row)

    def drop_piece(self, column):
        for i in range(5, -1, -1):
            if self.board[i][column] == ' ':
                self.board[i][column] = self.current_player
                return True
        return False

    def check_winner(self):
        # Check horizontal locations for win
        for c in range(7-3):
            for r in range(6):
                if self.board[r][c] == self.current_player and self.board[r][c+1] == self.current_player and self.board[r][c+2] == self.current_player and self.board[r][c+3] == self.current_player:
                    return True

        # Check vertical locations for win
        for c in range(7):
            for r in range(6-3):
                if self.board[r][c] == self.current_player and self.board[r+1][c] == self.current_player and self.board[r+2][c] == self.current_player and self.board[r+3][c] == self.current_player:
                    return True

        # Check positively sloped diagonals
        for c in range(7-3):
            for r in range(6-3):
                if self.board[r][c] == self.current_player and self.board[r+1][c+1] == self.current_player and self.board[r+2][c+2] == self.current_player and self.board[r+3][c+3] == self.current_player:
                    return True

        # Check negatively sloped diagonals
        for c in range(7-3):
            for r in range(3, 6):
                if self.board[r][c] == self.current_player and self.board[r-1][c+1] == self.current_player and self.board[r-2][c+2] == self.current_player and self.board[r-3][c+3] == self.current_player:
                    return True

        return False

    def play(self):
        while True:
            self.print_board()
            column = int(input(f"Player {self.current_player}'s turn. Choose a column: ")) - 1
            if self.drop_piece(column):
                if self.check_winner():
                    self.print_board()
                    print(f"Player {self.current_player} wins!")
                    break
                self.current_player = 'O' if self.current_player == 'X' else 'X'
            else:
                print("Invalid move. Try again.")

if __name__ == "__main__":
    game = Connect4()
    game.play()
```

This program creates a 7x6 grid and alternates between two players ('X' and 'O'). The `drop_piece` method allows a player to drop a piece into the grid by specifying a column. The `check_winner` method checks the grid for a winner by examining all possible winning combinations. The `play` method is the main game loop where players take turns dropping pieces into the grid.

