Here's a simple example of how to create a Sierpinski triangle in XAML using a custom control. This example uses a canvas to draw the triangle and its recursive iterations.

**SierpinskiTriangle.xaml**
```xaml
<UserControl
    x:Class="SierpinskiTriangle.SierpinskiTriangleControl"
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    xmlns:d="http://schemas.microsoft.com/expression/blend/2008"
    xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006"
    mc:Ignorable="d"
    d:DesignHeight="300"
    d:DesignWidth="300">
    <Canvas x:Name="myCanvas" Width="300" Height="300" />
</UserControl>
```

**SierpinskiTriangle.xaml.cs**
```csharp
using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;

public partial class SierpinskiTriangleControl : UserControl
{
    public SierpinskiTriangleControl()
    {
        InitializeComponent();

        DrawSierpinskiTriangle(myCanvas, new Point(150, 25), 6);
    }

    private void DrawSierpinskiTriangle(Canvas myCanvas, Point p1, int iteration)
    {
        if (iteration == 0)
        {
            // Draw the base triangle
            Line line = new Line
            {
                X1 = p1.X,
                Y1 = p1.Y,
                X2 = 150,
                Y2 = 275,
                Stroke = Brushes.Black,
                StrokeThickness = 2
            };
            myCanvas.Children.Add(line);

            line = new Line
            {
                X1 = 150,
                Y1 = 275,
                X2 = 300,
                Y2 = 25,
                Stroke = Brushes.Black,
                StrokeThickness = 2
            };
            myCanvas.Children.Add(line);

            line = new Line
            {
                X1 = 300,
                Y1 = 25,
                X2 = 150,
                Y2 = 275,
                Stroke = Brushes.Black,
                StrokeThickness = 2
            };
            myCanvas.Children.Add(line);
        }
        else
        {
            // Draw three smaller triangles
            DrawSierpinskiTriangle(myCanvas, new Point(p1.X - (150 / 2) * Math.Pow(0.5, iteration), p1.Y - (150 * Math.Pow(0.5, iteration))), iteration - 1);
            DrawSierpinskiTriangle(myCanvas, new Point(p1.X + (150 / 2) * Math.Pow(0.5, iteration), p1.Y + (150 * Math.Pow(0.5, iteration))), iteration - 1);
            DrawSierpinskiTriangle(myCanvas, new Point(p1.X, p1.Y + (150 * Math.Pow(0.5, iteration))), iteration - 1);
        }
    }
}
```

To use this control in a XAML file, you would do something like this:

**MainWindow.xaml**
```xaml
<Window x:Class="MainWindow"
        xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        xmlns:local="clr-namespace:SierpinskiTriangle"
        Title="Sierpinski Triangle" Height="300" Width="300">
    <Grid>
        <local:SierpinskiTriangleControl />
    </Grid>
